import{_ as t,o,c as a,a2 as s}from"./chunks/framework.M7K9TQZf.js";const u=JSON.parse('{"title":"Prop conventions","description":"One vocabulary, shared by every component. A size of md is the same height everywhere, and an idea that already has a name does not get a second one.","frontmatter":{"title":"Prop conventions","order":3},"headers":[],"relativePath":"design/prop-conventions.md","filePath":"en/design/prop-conventions.md","lastUpdated":1788614679000}'),n={name:"design/prop-conventions.md"};function d(i,e,r,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="prop-conventions" tabindex="-1">Prop conventions <a class="header-anchor" href="#prop-conventions" aria-label="Permalink to &quot;Prop conventions&quot;">​</a></h1><p class="plass-lede">One vocabulary, shared by every component. A <code>size</code> of <code>md</code> is the same height everywhere, and an idea that already has a name does not get a second one.</p><h2 id="the-five-shared-axes" tabindex="-1">The five shared axes <a class="header-anchor" href="#the-five-shared-axes" aria-label="Permalink to &quot;The five shared axes&quot;">​</a></h2><p>They live in <code>src/types.ts</code> and every styled component draws from them.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Means</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>&#39;solid&#39; | &#39;glass&#39; | &#39;ghost&#39;</code></td><td>What the surface is made of</td></tr><tr><td><code>size</code></td><td><code>&#39;xs&#39; | &#39;sm&#39; | &#39;md&#39; | &#39;lg&#39; | &#39;xl&#39;</code></td><td>Height and type scale, together</td></tr><tr><td><code>color</code></td><td>six role names</td><td>Which semantic family</td></tr><tr><td><code>density</code></td><td><code>&#39;default&#39; | &#39;compact&#39;</code></td><td>Padding, and only padding</td></tr><tr><td><code>elevation</code></td><td><code>0 | 1 | 2 | 3</code></td><td>How far off the page</td></tr></tbody></table><h3 id="variant-names-a-material" tabindex="-1"><code>variant</code> names a material <a class="header-anchor" href="#variant-names-a-material" aria-label="Permalink to &quot;`variant` names a material&quot;">​</a></h3><p><code>solid</code>, <code>glass</code>, <code>ghost</code>, not <code>filled</code>, <code>outlined</code>, <code>text</code>. The three words are the three answers to the question the <a href="./design-language">design language</a> makes every surface answer, and naming them after what they <em>are</em> rather than after what they look like is what keeps the answer consistent when a component is hard to place.</p><p>The one place the same word means two things is <code>solid</code> on something typed into: there it is the <strong>well</strong>, not a tinted pane. See <a href="./../components/inputs/text-field#variant">PlTextField</a>.</p><h3 id="size-is-one-decision" tabindex="-1"><code>size</code> is one decision <a class="header-anchor" href="#size-is-one-decision" aria-label="Permalink to &quot;`size` is one decision&quot;">​</a></h3><p>Height and type scale move together, always. There is no <code>size=&quot;md&quot; textSize=&quot;lg&quot;</code>, because two controls of the same <code>size</code> that are not the same height are two controls that will never line up in a row.</p><h3 id="color-is-a-role-never-a-value" tabindex="-1"><code>color</code> is a role, never a value <a class="header-anchor" href="#color-is-a-role-never-a-value" aria-label="Permalink to &quot;`color` is a role, never a value&quot;">​</a></h3><p>Six names, no arbitrary colours. A component that needs a colour that is not one of the six is asking for a design token, and that is a change to <a href="./color">Colour</a> rather than a prop.</p><h3 id="density-is-padding" tabindex="-1"><code>density</code> is padding <a class="header-anchor" href="#density-is-padding" aria-label="Permalink to &quot;`density` is padding&quot;">​</a></h3><p>It never touches the height and never touches the type scale. A compact control and a default control of the same <code>size</code> sit on the same baseline.</p><h3 id="elevation-defaults-differ-and-the-default-is-the-statement" tabindex="-1"><code>elevation</code> defaults differ, and the default is the statement <a class="header-anchor" href="#elevation-defaults-differ-and-the-default-is-the-statement" aria-label="Permalink to &quot;`elevation` defaults differ, and the default is the statement&quot;">​</a></h3><p><code>0</code> on anything that holds content, <code>1</code> on anything pressed. A key rests <strong>on</strong> the sheet; a field is cut <strong>into</strong> it. Where a component&#39;s default is not what you would guess, its props table says so.</p><h2 id="naming-rules" tabindex="-1">Naming rules <a class="header-anchor" href="#naming-rules" aria-label="Permalink to &quot;Naming rules&quot;">​</a></h2><p>These are the rules a new component is checked against.</p><ul><li><strong>Do not invent a second spelling for an idea that already has one.</strong> If a component needs &quot;how big&quot;, it is <code>size</code>. If it needs &quot;which semantic colour&quot;, it is <code>color</code>. A <code>scale</code>, a <code>tone</code> or an <code>intent</code> prop is a fork in the vocabulary.</li><li><strong>Boolean props are named for the state they turn on</strong>, and default to <code>false</code>: <code>loading</code>, <code>readOnly</code>, <code>disabled</code>, <code>fullWidth</code>, <code>multiline</code>, <code>invalid</code>.</li><li><strong>Slots are <code>ReactNode</code>, named for where they go</strong>: <code>startIcon</code>, <code>endIcon</code>, <code>label</code>, <code>description</code>, <code>error</code>. Never <code>renderIcon</code>, never <code>iconLeft</code>.</li><li><strong><code>start</code>/<code>end</code>, never <code>left</code>/<code>right</code>.</strong> They flip under RTL; the physical words do not.</li><li><strong>Durations and delays are numbers in milliseconds</strong>, never CSS strings. A prop typed <code>string</code> invites <code>&#39;0.4s&#39;</code>, and then two components on one screen are written in two units.</li><li><strong><code>render</code> is the escape hatch</strong>, spelled the same way everywhere, Base UI&#39;s own prop, passed through. It replaces the element without changing the surface.</li><li><strong>Native attributes pass through.</strong> A component that wraps an <code>&lt;input&gt;</code> takes every <code>&lt;input&gt;</code> attribute, minus the ones that collide with an axis above (<code>color</code>, <code>size</code>).</li></ul><h2 id="binding-a-key" tabindex="-1">Binding a key <a class="header-anchor" href="#binding-a-key" aria-label="Permalink to &quot;Binding a key&quot;">​</a></h2><p><code>PlTextField</code>, <code>PlNumberField</code>, <code>PlOtpField</code>, <code>PlCombobox</code> and <code>PlSelect</code> take a <strong><code>hotKeys</code></strong> map: a chord, and what pressing it does.</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlTextField</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hotKeys</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Mod+Enter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: save, Escape: cancel }} /&gt;</span></span></code></pre></div><p>Three rules hold across all five.</p><ul><li><strong>The chord is spelled the way a key cap is spelled</strong>: the same vocabulary <a href="./../components/display/hot-keys"><code>PlHotKeys</code></a> draws. <code>Mod</code> resolves per platform (⌘ on a Mac, <kbd>Ctrl</kbd> everywhere else), and <code>Esc</code>, <code>Return</code>, <code>Cmd</code> and <code>Option</code> fold onto the same keys their caps do. A shortcut a component displays and a shortcut it binds must be one string, or the cap on the screen is a claim nobody checked.</li><li><strong>A modifier is checked in both directions.</strong> <code>Enter</code> does not fire on <kbd>Shift</kbd>+<kbd>Enter</kbd>, so a field that saves on Enter does not also save on every chord that happens to end in one.</li><li><strong>A chord that matches is consumed.</strong> The handler runs and the key goes no further, not to the control&#39;s own key handling, not to the form, not to the dialog above it. Bind chords rather than letters: a field with <code>{ a: … }</code> cannot type an <code>a</code>.</li></ul><div class="plass-fw" data-fw="react"><p><code>hotKeys</code> sits on the <strong>control</strong> rather than on the stack around it, so a chord is answered by the thing that has the focus. It is a convenience over <code>onKeyDown</code>, not a replacement: the raw handler is still there, still passes through to the same element, and runs <strong>first</strong>, if it calls <code>preventDefault()</code>, the map is skipped.</p></div><div class="plass-fw" data-fw="flutter"><p>The map is bound closer to the focused node than the widget&#39;s own key handling, which is what lets a caller take a key from the control. <code>PlSelect</code> is the one place that cannot be done by nesting, a <code>FocusableActionDetector</code> binds Enter closer than anything a field can wrap around it, so the trigger <strong>stands down</strong> from Enter instead, whenever the map asks for it.</p><p>There is no <code>onKeyDown</code> underneath this one. A widget that needs finer key handling than a chord map wraps the field in its own <code>Focus</code>.</p></div><h2 id="styling-a-component-from-outside" tabindex="-1">Styling a component from outside <a class="header-anchor" href="#styling-a-component-from-outside" aria-label="Permalink to &quot;Styling a component from outside&quot;">​</a></h2><div class="plass-fw" data-fw="react"><p>Four channels, and they are not interchangeable. Reach for them in this order.</p><h3 id="_1-classname-for-layout" tabindex="-1">1. <code>className</code>, for layout <a class="header-anchor" href="#_1-classname-for-layout" aria-label="Permalink to &quot;1. `className`, for layout&quot;">​</a></h3><p>A <code>className</code> lands on the one element a reader would point at and call the component: a <code>PlButton</code>&#39;s <code>&lt;button&gt;</code>, a <code>PlModal</code>&#39;s sheet, a field&#39;s stack. It joins the component&#39;s own classes rather than replacing them, and each component&#39;s Props section says which element that is.</p><p>It is the right channel for where a component sits and how much room it takes, a <code>w-full</code>, a margin, a grid position. Those are properties the library does not set on itself, so nothing is competing for them.</p><h3 id="_2-classnames-for-the-parts-classname-cannot-reach" tabindex="-1">2. <code>classNames</code>, for the parts <code>className</code> cannot reach <a class="header-anchor" href="#_2-classnames-for-the-parts-classname-cannot-reach" aria-label="Permalink to &quot;2. `classNames`, for the parts `className` cannot reach&quot;">​</a></h3><p>Some components draw more than one thing. A field draws its label and the two lines of text under it; a portalled surface paints a scrim behind itself. <code>classNames</code> is a map to those parts, and only to those. The component&#39;s own surface keeps one prop and not two, so there is never a question of which of them wins.</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlTextField</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  label</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Email&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  className</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;w-full&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  classNames</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ control: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;font-mono&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, error: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;italic&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>The keys mean the same part everywhere they appear: <code>label</code>, <code>control</code>, <code>description</code> and <code>error</code> on a labelled control; <code>backdrop</code> on a portalled surface.</p><h3 id="_3-tokens-for-anything-the-component-already-paints" tabindex="-1">3. Tokens, for anything the component already paints <a class="header-anchor" href="#_3-tokens-for-anything-the-component-already-paints" aria-label="Permalink to &quot;3. Tokens, for anything the component already paints&quot;">​</a></h3><p><strong>This is the one that always works</strong>, and the reason is worth understanding rather than taking on trust.</p><p>The library writes its edge, its shadow, its focus ring and its fill as Tailwind <em>arbitrary properties</em>, <code>[box-shadow:var(--p-elev),var(--p-lift)]</code> and the like. Tailwind sorts those <strong>last</strong> in the generated stylesheet, and a stylesheet is what decides which of two classes wins. Appending <code>shadow-none</code> after one puts it earlier in the file, so it loses.</p><p>The custom property underneath does not, because an inline <code>style</code> beats every class there is. See <a href="./color#setting-a-token-from-react">Setting a token from React</a>.</p><h3 id="the-limits-of-a-plain-classname" tabindex="-1">The limits of a plain <code>className</code> <a class="header-anchor" href="#the-limits-of-a-plain-classname" aria-label="Permalink to &quot;The limits of a plain `className`&quot;">​</a></h3><p>The order of two classes in an attribute means nothing. What decides is their order in the generated stylesheet, and Tailwind&#39;s sort is by <em>name</em> (numeric scales ascending, everything else alphabetically), which has no relationship to what a caller intended.</p><table tabindex="0"><thead><tr><th>The component writes</th><th>You write</th><th>Wins</th></tr></thead><tbody><tr><td><code>text-sm</code> (at <code>size=&quot;sm&quot;</code>)</td><td><code>text-lg</code></td><td><strong>the component</strong></td></tr><tr><td><code>bg-transparent</code> (at <code>variant=&quot;ghost&quot;</code>)</td><td><code>bg-red-500</code></td><td><strong>the component</strong></td></tr><tr><td><code>w-full</code> (at <code>fullWidth</code>)</td><td><code>w-auto</code></td><td><strong>the component</strong></td></tr><tr><td><code>h-10</code> (at <code>size=&quot;md&quot;</code>)</td><td><code>h-8</code></td><td><strong>the component</strong></td></tr><tr><td><code>[box-shadow:…]</code></td><td><code>shadow-none</code></td><td><strong>the component</strong></td></tr><tr><td><code>h-10</code></td><td><code>h-12</code></td><td>you</td></tr><tr><td><code>rounded-(--plass-radius-md)</code></td><td><code>rounded-3xl</code></td><td>you</td></tr><tr><td><code>p-4</code></td><td><code>px-8</code></td><td>you</td></tr></tbody></table><p>Two ways out, both reliable:</p><ul><li><strong>A token</strong>, per the section above. It is the only channel that reaches an arbitrary property at all.</li><li><strong>The <code>!</code> modifier</strong>: <code>shadow-none!</code>, <code>text-lg!</code>. Nothing in the library is <code>!important</code>, so an important utility always wins. The one place it is not optional is <code>PlTextLink</code>, whose <code>.plass-link.plass-link</code> rule outranks a single class whatever the order.</li></ul><h3 id="the-stylesheet-you-imported" tabindex="-1">The stylesheet you imported <a class="header-anchor" href="#the-stylesheet-you-imported" aria-label="Permalink to &quot;The stylesheet you imported&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Import</th><th>What decides a conflict</th></tr></thead><tbody><tr><td><code>plass-ui/tailwind.css</code> or <code>plass-ui/css/*.css</code></td><td>Tailwind&#39;s sort, per the table above. Your classes and the components&#39; are generated in one pass</td></tr><tr><td><code>plass-ui/styles.css</code></td><td><strong>The order of your <code>@import</code>s.</strong> The package&#39;s CSS is already compiled, so it cannot take part in your Tailwind build; import it <em>before</em> your own stylesheet or it outranks everything in it</td></tr></tbody></table><h3 id="_4-render-when-the-element-itself-is-wrong" tabindex="-1">4. <code>render</code>, when the element itself is wrong <a class="header-anchor" href="#_4-render-when-the-element-itself-is-wrong" aria-label="Permalink to &quot;4. `render`, when the element itself is wrong&quot;">​</a></h3><p>Base UI&#39;s own prop, passed through where it makes sense, <code>&lt;PlButton render={&lt;a href=&quot;/pricing&quot; /&gt;}&gt;</code>. It replaces the element without changing the surface, which is the thing no amount of CSS can do.</p></div><h2 id="rules-for-a-state-prop" tabindex="-1">Rules for a state prop <a class="header-anchor" href="#rules-for-a-state-prop" aria-label="Permalink to &quot;Rules for a state prop&quot;">​</a></h2><p>Three states exist and each has its own axis; a fourth that overlaps one of them is a bug in the API rather than in the styling.</p><table tabindex="0"><thead><tr><th>State</th><th>Native attribute</th><th>Focus</th><th>Fires handlers</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>yes</td><td>lost</td><td>no</td></tr><tr><td><code>readOnly</code></td><td><code>aria-disabled</code></td><td>kept</td><td>no</td></tr><tr><td><code>loading</code></td><td><code>aria-disabled</code></td><td>kept</td><td>no</td></tr></tbody></table><p><code>loading</code> and <code>readOnly</code> keep focus on purpose: dropping out of the tab order costs keyboard users their sense of where they are on the page.</p>',32)])])}const g=t(n,[["render",d]]);export{u as __pageData,g as default};
